Producers                Bounded queue              Consumers

  P1 --put()--+                                +--take()-- C1
              +--->  [ job | job | job | _ ] --+
  P2 --put()--+        full  -> put() blocks     +--take()-- C2
                       empty -> take() blocks

BlockingQueue<Job> q = new ArrayBlockingQueue<>(100);

// producer
q.put(job);                 // waits if full

// consumer
while (true) {
    Job j = q.take();       // waits if empty
    process(j);
}

// Producer adding to a FULL queue
q.put(job);                          // blocks until space (maybe forever)
boolean ok = q.offer(job);           // returns false at once, never blocks
boolean ok = q.offer(job, 2, TimeUnit.SECONDS);
                                     // waits up to 2s, then false

if (!ok) { reject(job); }            // e.g. HTTP 503 / drop / retry

            queue full
   put()  ----------------> wait ..... until space   (may hang)
   offer() ---------------> false immediately
   offer(t) --------------> wait <= t ---> space? true : false
